import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
// Helper function to calculate rotation around a point
// Required for IK (Inverse Kinematics) simulated legs attached to a rotating body
const rotatePoint = (cx: number, cy: number, x: number, y: number, angleDegrees: number) => {
  const rad = (angleDegrees * Math.PI) / 180;
  const cos = Math.cos(rad);
  const sin = Math.sin(rad);
  return {
    x: cos * (x - cx) - sin * (y - cy) + cx,
    y: sin * (x - cx) + cos * (y - cy) + cy,
  };
};



export type LemonDanceProps = Record<string, any>;

// Generates a 2D displacement map that maps every pixel in a block to its center.
// Using this with an SVG feDisplacementMap perfectly quantizes/pixelates the source vector graphic!
const getPixelMapUri = (size: number) => {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">
  <defs>
    <linearGradient id="r" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#f00"/>
      <stop offset="100%" stop-color="#000"/>
    </linearGradient>
    <linearGradient id="g" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#0f0"/>
      <stop offset="100%" stop-color="#000"/>
    </linearGradient>
  </defs>
  <rect width="${size}" height="${size}" fill="url(#r)"/>
  <rect width="${size}" height="${size}" fill="url(#g)" style="mix-blend-mode: screen;"/>
</svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
};

const LemonDance: React.FC<LemonDanceProps> = ({
  backgroundColor = "#D4CF3E",
  transparentBackground = false,
  durationInSeconds = 5,
  lemonColorPrimary = "#F0E846",
  lemonColorHighlight = "#FDFB8E",
  lemonColorShadow = "#C3BA23",
  glassesColor = "#333235",
  leafColor = "#50B14A",
  stemColor = "#9A7249",
  danceSpeedMulti = 1.0,
  pixelate = true,
  pixelSize = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Parser safety for background
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Logic (The Dance) ---
  // A standard dance cycle is 30 frames (1 second at 30fps)
  const baseCycleFrames = 30;
  const cycleFrames = baseCycleFrames / danceSpeedMulti;
  
  // Progress goes from 0 to 1 over one cycle, then loops
  const cycleProgress = (frame % cycleFrames) / cycleFrames;

  // Sway side to side (Sine wave)
  const swayMax = 50;
  const swayX = Math.sin(cycleProgress * Math.PI * 2) * swayMax;

  // Bob up and down (Double-frequency cosine wave for two dips per cycle)
  // Maps cosine (-1 to 1) to (0 to 1) where 1 is the lowest dip
  const bobPhase = Math.cos(cycleProgress * Math.PI * 4);
  const bobNormalized = (bobPhase * -1 + 1) / 2;
  const bobMax = 45;
  const bobY = bobNormalized * bobMax;

  // Slight rotation coupled with the sway for a natural groove
  const rotationDegrees = swayX * 0.15; // Max ~7.5 degrees

  // --- Kinematics & Positioning ---
  // Base coordinates for the lemon body center
  const cx = 540;
  const cy = 540;

  // Where the legs attach to the body in its default upright state
  const leftAnchorBase = { x: 440, y: 830 };
  const rightAnchorBase = { x: 640, y: 830 };

  // Calculate where the leg anchors are in world space AFTER body rotation and translation
  const leftAnchorRotated = rotatePoint(cx, cy, leftAnchorBase.x, leftAnchorBase.y, rotationDegrees);
  const leftAnchorWorld = {
    x: leftAnchorRotated.x + swayX,
    y: leftAnchorRotated.y + bobY,
  };

  const rightAnchorRotated = rotatePoint(cx, cy, rightAnchorBase.x, rightAnchorBase.y, rotationDegrees);
  const rightAnchorWorld = {
    x: rightAnchorRotated.x + swayX,
    y: rightAnchorRotated.y + bobY,
  };

  // Fixed positions for the feet on the "ground"
  const leftFootX = 380;
  const rightFootX = 700;
  const footY = 980;

  // Dynamic SVG Paths for legs that bend
  // Uses a quadratic bezier (Q) to bow the knee outwards slightly as it compresses
  const leftKneeX = Math.min(leftAnchorWorld.x, leftFootX) - 30;
  const leftLegPath = `M ${leftAnchorWorld.x} ${leftAnchorWorld.y} Q ${leftKneeX} ${(leftAnchorWorld.y + footY) / 2} ${leftFootX} ${footY}`;

  const rightKneeX = Math.max(rightAnchorWorld.x, rightFootX) + 30;
  const rightLegPath = `M ${rightAnchorWorld.x} ${rightAnchorWorld.y} Q ${rightKneeX} ${(rightAnchorWorld.y + footY) / 2} ${rightFootX} ${footY}`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", justifyContent: "center", alignItems: "center" }}>
      {/* 
        Using a 1080x1080 viewBox scales perfectly within the absolute fill, 
        maintaining crisp SVG rendering regardless of actual output resolution 
      */}
      <svg viewBox="0 0 1080 1080" style={{ width: "100%", height: "100%", overflow: "visible" }}>
        <defs>
          <radialGradient id="lemonGradient" cx="35%" cy="30%" r="75%">
            <stop offset="0%" stopColor={lemonColorHighlight} />
            <stop offset="50%" stopColor={lemonColorPrimary} />
            <stop offset="100%" stopColor={lemonColorShadow} />
          </radialGradient>
          
          {pixelate && (
            <filter id="pixelate" x="0" y="0" width="1080" height="1080" filterUnits="userSpaceOnUse" colorInterpolationFilters="sRGB">
              <feImage width={pixelSize} height={pixelSize} href={getPixelMapUri(pixelSize)} result="map" />
              <feTile in="map" result="tiledMap" />
              <feDisplacementMap in="SourceGraphic" in2="tiledMap" scale={pixelSize} xChannelSelector="R" yChannelSelector="G" result="displaced" />
              {/* Threshold alpha to ensure perfectly crisp retro edges without soft antialiasing */}
              <feComponentTransfer in="displaced">
                <feFuncA type="discrete" tableValues="0 1" />
              </feComponentTransfer>
            </filter>
          )}
        </defs>

        <g filter={pixelate ? "url(#pixelate)" : undefined} style={{ transition: "none" }}>
          {/* --- LEGS (Rendered behind the body) --- */}
          <g stroke="#262626" fill="none" style={{ transition: "none" }}>
            {/* Left Leg & Foot */}
            <path d={leftLegPath} strokeWidth="22" strokeLinecap="round" />
            <path d={`M ${leftFootX - 40} ${footY} L ${leftFootX + 30} ${footY}`} strokeWidth="30" strokeLinecap="round" />
            
            {/* Right Leg & Foot */}
            <path d={rightLegPath} strokeWidth="22" strokeLinecap="round" />
            <path d={`M ${rightFootX - 30} ${footY} L ${rightFootX + 40} ${footY}`} strokeWidth="30" strokeLinecap="round" />
          </g>

          {/* --- BODY GROUP (Animated together) --- */}
          <g transform={`translate(${swayX}, ${bobY}) rotate(${rotationDegrees} ${cx} ${cy})`} style={{ transition: "none" }}>
            {/* Stem */}
            <path 
              d="M 525 185 Q 530 100 550 50 L 580 60 Q 560 120 565 190 Z" 
              fill={stemColor} 
            />
            
            {/* Leaf */}
            <path 
              d="M 550 100 C 400 30, 260 80, 260 180 C 350 240, 480 200, 560 120 Z" 
              fill={leafColor} 
            />

            {/* Lemon Body */}
            <path 
              d="M 540 180 C 740 190, 880 400, 810 640 C 760 820, 640 890, 540 910 C 440 890, 320 820, 270 640 C 200 400, 340 190, 540 180 Z" 
              fill="url(#lemonGradient)" 
            />

            {/* Sunglasses (Wayfarer Style) */}
            <path 
              d="M 270 420 Q 540 450 810 420 L 780 540 C 700 640, 600 590, 570 540 Q 540 520 510 540 C 480 590, 380 640, 300 540 Z" 
              fill={glassesColor} 
              strokeLinejoin="round"
            />

            {/* Smirk / Mouth */}
            <path 
              d="M 430 650 Q 520 700 620 620" 
              fill="none" 
              stroke="#262626" 
              strokeWidth="20" 
              strokeLinecap="round" 
            />
          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default LemonDance;